// =====================
// NORMALIZER v2 — canonici dallo sheet
// =====================

// --- Rubrica dallo sheet ---
const book = $input.all().map(i => i.json).filter(r => r["Autisti"]);

// --- Telegram update (primo item del trigger) ---
const root = $('Telegram Trigger1').first().json || {};
const u = root.message || {};
const cb = root.callback_query || {};

// =====================
// UTILS
// =====================
function stripDiacritics(s) {
  return (s || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "");
}

function normalizeKey(s) {
  return stripDiacritics(s)
    .toLowerCase()
    .trim()
    .replace(/[.,;:!?"'`´^~_*()\[\]{}<>|\\\/+-]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function variants(sNorm) {
  const parts = sNorm.split(" ").filter(Boolean);
  const out = new Set([sNorm]);
  if (parts.length === 2) out.add(`${parts[1]} ${parts[0]}`);
  if (parts.length >= 3) out.add(`${parts[parts.length - 1]} ${parts.slice(0, parts.length - 1).join(" ")}`);
  return [...out].filter(Boolean);
}

// =====================
// FUZZY (Levenshtein)
// =====================
function levenshtein(a, b) {
  a = a || ""; b = b || "";
  const m = a.length, n = b.length;
  if (m === 0) return n;
  if (n === 0) return m;
  let prev = Array.from({ length: n + 1 }, (_, i) => i);
  let curr = new Array(n + 1);
  for (let i = 1; i <= m; i++) {
    curr[0] = i;
    const ca = a.charCodeAt(i - 1);
    for (let j = 1; j <= n; j++) {
      const cb = b.charCodeAt(j - 1);
      curr[j] = Math.min(prev[j] + 1, curr[j - 1] + 1, prev[j - 1] + (ca === cb ? 0 : 1));
    }
    [prev, curr] = [curr, prev];
  }
  return prev[n];
}

function similarity(a, b) {
  const maxLen = Math.max(a.length, b.length);
  return maxLen === 0 ? 1 : 1 - levenshtein(a, b) / maxLen;
}

function splitName(norm) {
  const parts = (norm || "").split(" ").filter(Boolean);
  if (parts.length === 0) return { first: "", last: "" };
  if (parts.length === 1) return { first: parts[0], last: "" };
  return { first: parts[0], last: parts[parts.length - 1] };
}

// =====================
// INDICE NORMALIZZATO (dallo sheet)
// =====================
const canonList = book.map(x => {
  const name = String(x["Autisti"]);
  const norm = normalizeKey(name);
  const t = splitName(norm);
  return {
    name,
    norm,
    first: t.first,
    last: t.last,
    chat_id: x["chat id"] || null,
    gruppo_id: x["gruppo id"] || null,
    email: x["mail"] || null,
  };
});

const canonMap = new Map(canonList.map(c => [c.norm, c]));

// =====================
// SMART FUZZY
// =====================
function smartFuzzyAutista(rawNorm) {
  const { first: rawFirst, last: rawLast } = splitName(rawNorm);
  if (!rawLast) return null;

  const scored = canonList.map(c => {
    const sLast = similarity(rawLast, c.last);
    const sFirst = similarity(rawFirst, c.first);
    const score = 0.7 * sLast + 0.3 * sFirst;
    return { ...c, score, sFirst, sLast };
  }).sort((a, b) => b.score - a.score);

  const best = scored[0];
  const second = scored[1] || { score: 0 };
  const gap = best.score - second.score;
  const minFirstDynamic = best.sLast >= 0.98 ? 0.70 : 0.80;

  if (best.score >= 0.90 && best.sLast >= 0.92 && best.sFirst >= minFirstDynamic && gap >= 0.03) {
    return { entry: best, MatchType: `smart_fuzzy:${best.score.toFixed(3)}` };
  }
  return null;
}

// =====================
// NORMALIZE AUTISTA
// =====================
function normalizeAutistaFromRoot(root) {
  const sources = [
    root.message?.from,
    root.callback_query?.from,
    root.callback_query?.message?.chat,
  ];

  let first = "", last = "", chat_id = "";
  for (const s of sources) {
    if (s?.first_name) {
      first = String(s.first_name || "");
      last = String(s.last_name || "");
      chat_id = String(s.id ?? "");
      break;
    }
  }

  const raw = `${first} ${last}`.replace(/\s+/g, " ").trim();
  const rawNorm = normalizeKey(raw);

  // 1) match diretto
  if (canonMap.has(rawNorm)) {
    const e = canonMap.get(rawNorm);
    return { Autista: e.name, AutistaRaw: raw, MatchType: "direct", ChatId: chat_id };
  }

  // 2) varianti
  for (const v of variants(rawNorm)) {
    if (canonMap.has(v)) {
      const e = canonMap.get(v);
      return { Autista: e.name, AutistaRaw: raw, MatchType: "variant", ChatId: chat_id };
    }
  }

  // 3) inclusione
  const incl = canonList.filter(c =>
    c.norm.includes(rawNorm) || rawNorm.includes(c.norm)
  );
  if (incl.length === 1) {
    return { Autista: incl[0].name, AutistaRaw: raw, MatchType: "inclusion", ChatId: chat_id };
  }

  // 4) smart fuzzy
  const sf = smartFuzzyAutista(rawNorm);
  if (sf) {
    return { Autista: sf.entry.name, AutistaRaw: raw, MatchType: sf.MatchType, ChatId: chat_id };
  }

  // 5) fallback
  return { Autista: raw, AutistaRaw: raw, MatchType: "fallback_raw", ChatId: chat_id };
}

// =====================
// ROUTER
// =====================
const aut = normalizeAutistaFromRoot(root);

const out = {
  kind: "",
  text: "",
  file_id: "",
  mime: "",
  chat_id: cb?.message?.chat?.id ?? u?.chat?.id ?? aut.ChatId ?? "",
  message_id: cb?.message?.message_id ?? u?.message_id ?? "",
  callback_data: cb?.data ?? "",
  Autista: aut.Autista,
  AutistaRaw: aut.AutistaRaw,
  MatchType: aut.MatchType,
  ChatId: aut.ChatId,
};

if (cb?.data) { out.kind = "callback"; out.text = String(cb.data || "").trim(); return [{ json: out }]; }
if (u?.text)  { out.kind = "text";     out.text = String(u.text || "").trim();  return [{ json: out }]; }

if (Array.isArray(u.photo) && u.photo.length) {
  out.kind = "image";
  out.file_id = u.photo[u.photo.length - 1].file_id;
  out.text = String(u.caption || "").trim();
  return [{ json: out }];
}

if (u?.voice?.file_id)    { out.kind = "voice";    out.file_id = u.voice.file_id;    out.text = String(u.caption || "").trim(); return [{ json: out }]; }
if (u?.audio?.file_id)    { out.kind = "audio";    out.file_id = u.audio.file_id;    out.text = String(u.caption || "").trim(); return [{ json: out }]; }
if (u?.document?.file_id) { out.kind = "document"; out.file_id = u.document.file_id; out.mime = String(u.document.mime_type || ""); out.text = String(u.caption || "").trim(); return [{ json: out }]; }

out.kind = "unknown";
out.text = String(u.caption || "").trim();
return [{ json: out }];

/**
 * n8n Code node (JavaScript) - Run Once for All Items
 * INPUT: items[0].json.data = [ { servizio }, ... ]
 * OUTPUT: 1 item riepilogativo, con merge sulla riga esistente se presente
 * FIX 14/07/2026 (Claude):
 *  - durate day-aware: i servizi dopo mezzanotte non producono più ~24h
 *  - guardia refusi: fine<inizio con wrap >6h = orario sospetto → |diff| + ⚠️ nel riepilogo
 *    (i servizi sospetti NON entrano nel calcolo dello span della Durata totale)
 *  - dedup servizi (nel batch e contro la riga già esistente di oggi)
 *  - input vuoto / nessun servizio nuovo → return [] (NON scrive righe vuote)
 *  - Durata totale mai < Durata effettiva
 */

// ------------------ HELPERS ------------------
function s(v) {
  return String(v ?? "").trim();
}

function pick(obj, keys) {
  for (const k of keys) {
    const v = obj?.[k];
    if (v !== undefined && v !== null && s(v) !== "") return v;
  }
  return "";
}

function isTimeHHMM(x) {
  return /^([01]?\d|2[0-3]):[0-5]\d$/.test(s(x));
}

function timeToMin(x) {
  if (!isTimeHHMM(x)) return null;
  const [h, m] = s(x).split(":").map(Number);
  return h * 60 + m;
}

function toNumber(v) {
  if (typeof v === "number" && Number.isFinite(v)) return v;
  const n = Number(s(v).replace(",", "."));
  return Number.isFinite(n) ? n : null;
}

function round2(n) {
  return Number(Number(n).toFixed(2));
}

function hoursFromMinutesIT(min) {
  const hours = round2((Number(min) || 0) / 60);
  return hours.toFixed(2).replace(".", ",");
}

function parseHoursIT(str) {
  if (!str) return 0;
  const n = Number(String(str).replace(",", "."));
  return isNaN(n) ? 0 : n;
}

function isGarbage(v) {
  const t = s(v);
  return !t || t === ":" || t === "-" || (t.startsWith("{") && t.endsWith("}"));
}

// Durata di un singolo servizio (minuti) + flag refuso.
// fine < inizio: se il wrap (+24h) dà una durata <= 6h è un vero passaggio di
// mezzanotte; altrimenti è quasi certamente un refuso → uso |diff| e segnalo ⚠️.
function durataServizio(startMin, endMin) {
  // FUNZIONE UNICA ORE (24/07): invertiti/impossibili = sospetto a ZERO (non gonfia); mezzanotte vera <= 8h
  if (startMin === null || endMin === null) return { min: 0, sospetto: true };
  const diff = endMin - startMin;
  if (diff < 0) {
    const wrap = diff + 1440;
    if (wrap <= 480) return { min: wrap, sospetto: false };
    return { min: 0, sospetto: true };
  }
  if (diff > 1440) return { min: 0, sospetto: true };
  return { min: diff, sospetto: false };
}

// ------------------ UNIQUE ID ------------------
function generateId() {
  const d = new Date();
  const pad = (n) => String(n).padStart(2, "0");
  const date = d.getFullYear() + pad(d.getMonth() + 1) + pad(d.getDate());
  const time = pad(d.getHours()) + pad(d.getMinutes()) + pad(d.getSeconds());
  const rand = Math.random().toString(36).substring(2, 8).toUpperCase();
  return `CH-${date}-${time}-${rand}`;
}

// ------------------ RIGA ESISTENTE ------------------
const existingRow = $('Get row(s) in sheet3').first()?.json ?? null;
const IdChiusura = (existingRow?.Id && String(existingRow.Id).trim())
  ? String(existingRow.Id).trim()
  : generateId();

// ------------------ INPUT ------------------
const rows = Array.isArray(items?.[0]?.json?.data)
  ? items[0].json.data
  : [];

// ------------------ FIELD MAP ------------------
const F = {
  Data:    r => s(pick(r, ["Data"])),
  Mezzo:   r => s(pick(r, ["Veicolo", "Mezzo"])),
  Autista: r => s(pick(r, ["Autista"])),
  Da:      r => s(pick(r, ["Transfer > Da"])),
  Per:     r => s(pick(r, ["Transfer < Per"])),
  Inizio:  r => s(pick(r, ["Inizio"])),
  Fine:    r => s(pick(r, ["Fine"])),
  KmTot:   r => pick(r, ["Km Tot"]),
  KmInizio:r => pick(r, ["Km inizio"]),
  KmFine:  r => pick(r, ["Km fine"]),
};

function isValidRow(r) {
  if (!F.Da(r) || !F.Per(r)) return false;
  if (isGarbage(F.Inizio(r)) || isGarbage(F.Fine(r))) return false;
  if (!isTimeHHMM(F.Inizio(r)) || !isTimeHHMM(F.Fine(r))) return false;
  return true;
}

const valid = rows.filter(isValidRow);

// Niente da compattare → NON scrivere nulla (prima creava righe vuote)
if (!valid.length) {
  return [];
}

// ------------------ DEDUP SERVIZI ------------------
// Scarta doppioni nel batch e servizi già presenti nella riga di oggi
// (es. doppio click sul bottone "Fine servizio").
const oldRiepilogoText = existingRow?.["Riepilogo servizi"]
  ? String(existingRow["Riepilogo servizi"])
  : "";
const seen = new Set();
const nuovi = [];
for (const r of valid) {
  const sig = `${F.Da(r)}→${F.Per(r)} (${F.Inizio(r)}–${F.Fine(r)}`;
  if (seen.has(sig)) continue;
  if (oldRiepilogoText.includes(sig)) continue;
  seen.add(sig);
  nuovi.push(r);
}

if (!nuovi.length) {
  // Tutti i servizi erano già registrati: non scrivere nulla
  return [];
}

// ------------------ COMPATTA NUOVI SERVIZI (day-aware) ------------------
const Data    = F.Data(nuovi[0]);
const Autista = [...new Set(nuovi.map(F.Autista).filter(Boolean))].join(" / ");

let minAdjStart = null;
let maxAdjEnd = null;
let sommaMin = 0;
let offset = 0;
let prevRawStart = null;
const parti = [];

for (const r of nuovi) {
  const rawStart = timeToMin(F.Inizio(r));
  const rawEnd = timeToMin(F.Fine(r));
  const d = durataServizio(rawStart, rawEnd);
  sommaMin += d.min;

  parti.push(`${F.Da(r)}→${F.Per(r)} (${F.Inizio(r)}–${F.Fine(r)}${d.sospetto ? " ⚠️" : ""})`);

  // Orari sospetti: fuori dal calcolo dello span (inaffidabili)
  if (d.sospetto) continue;

  // Ordine di inserimento = ordine cronologico: se l'inizio "torna indietro"
  // rispetto al servizio precedente, siamo passati al giorno dopo.
  if (prevRawStart !== null && rawStart < prevRawStart) offset += 1440;
  prevRawStart = rawStart;

  const adjStart = rawStart + offset;
  const adjEnd = adjStart + d.min;
  if (minAdjStart === null || adjStart < minAdjStart) minAdjStart = adjStart;
  if (maxAdjEnd === null || adjEnd > maxAdjEnd) maxAdjEnd = adjEnd;
}

const RiepilogoServizi = parti.join(" | ");
const NumeroServizi = nuovi.length;

// Durata totale: dalla prima all'ultima ora, con giorni corretti.
// Non può mai essere inferiore alla somma dei singoli servizi.
let totMin = (minAdjStart !== null && maxAdjEnd !== null) ? (maxAdjEnd - minAdjStart) : 0;
if (totMin < sommaMin) totMin = sommaMin;
if (sommaMin > 1440) sommaMin = 1440; // tetto 24h
if (totMin > 1440) totMin = 1440;   // tetto 24h
const DurataTotale    = hoursFromMinutesIT(totMin);
const DurataEffettiva = hoursFromMinutesIT(sommaMin);

// Km
const KmTotali = round2(
  nuovi.reduce((a, r) => {
    const kmTot = toNumber(F.KmTot(r));
    if (kmTot !== null) return a + Math.abs(kmTot);
    const kmi = toNumber(F.KmInizio(r));
    const kmf = toNumber(F.KmFine(r));
    if (kmi !== null && kmf !== null) return a + Math.abs(kmf - kmi);
    return a;
  }, 0)
);

// Mezzo: dai nuovi servizi
const MezzoNuovo = [...new Set(nuovi.map(F.Mezzo).filter(Boolean))].join(" / ");

// ------------------ MERGE CON RIGA ESISTENTE ------------------
let finalRiepilogo     = RiepilogoServizi;
let finalNumeroServizi = NumeroServizi;
let finalMezzo         = MezzoNuovo;
let finalDurataTotale  = DurataTotale;
let finalDurataEffettiva = DurataEffettiva;
let finalKmTotali      = KmTotali;

if (existingRow?.["Riepilogo servizi"] && String(existingRow["Riepilogo servizi"]).trim()) {
  const oldRiepilogo = String(existingRow["Riepilogo servizi"]).trim();
  finalRiepilogo = oldRiepilogo + " | " + RiepilogoServizi;

  const oldNumero = parseInt(existingRow["n. servizi"] || "0", 10);
  finalNumeroServizi = (isNaN(oldNumero) ? 0 : oldNumero) + NumeroServizi;

  // Unisci veicoli senza duplicati
  const oldMezzo = String(existingRow["Mezzo"] || "").trim();
  const mezziSet = new Set([
    ...oldMezzo.split("/").map(x => x.trim()).filter(Boolean),
    ...MezzoNuovo.split("/").map(x => x.trim()).filter(Boolean)
  ]);
  finalMezzo = [...mezziSet].join(" / ");

  // Somma durate
  finalDurataTotale = (parseHoursIT(existingRow["Durata totale"]) + parseHoursIT(DurataTotale))
    .toFixed(2).replace(".", ",");
  finalDurataEffettiva = (parseHoursIT(existingRow["Durata effettiva"]) + parseHoursIT(DurataEffettiva))
    .toFixed(2).replace(".", ",");

  // Somma km
  const oldKm = toNumber(existingRow["Km totali"] ?? existingRow["KmTotali"] ?? 0) || 0;
  finalKmTotali = round2(oldKm + KmTotali);
}

// ------------------ OUTPUT ------------------
return [{
  json: {
    ok: true,
    errore: "",
    IdChiusura,
    Data,
    Mezzo: finalMezzo,
    Autista,
    NumeroServizi: finalNumeroServizi,
    RiepilogoServizi: finalRiepilogo,
    DurataTotale: finalDurataTotale,
    DurataEffettiva: finalDurataEffettiva,
    KmTotali: finalKmTotali,
  }
}];

// PARSE AI OUTPUT (text + buttons) for Rendicontazione v3 (no structured parser)
const item = $input.first()?.json ?? {};

function sanitize(s) {
  if (typeof s !== 'string') return '';
  let t = s;
  t = t.replace(/\*\*([^*]+)\*\*/g, '$1');
  t = t.replace(/\*([^*]+)\*/g, '$1');
  t = t.replace(/__([^_]+)__/g, '$1');
  t = t.replace(/_([^_]+)_/g, '$1');
  t = t.replace(/`([^`]+)`/g, '$1');
  t = t.replace(/\[([^\]]+)\]\([^)]+\)/g, '$1');
  return t.trim();
}
function stripFences(s) {
  if (typeof s !== 'string') return s;
  return s.trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
}
function tryJson(s) {
  if (typeof s !== 'string') return null;
  const t = stripFences(s).trim();
  if (!t) return null;
  try { return JSON.parse(t); } catch (e) {
    // try to extract first JSON block
    const m = t.match(/\{[\s\S]*\}/);
    if (m) { try { return JSON.parse(m[0]); } catch (e2) { return null; } }
    return null;
  }
}

// Pick raw output (AI Agent without parser typically returns { output: "..." } string)
let raw = item?.output ?? item;
let payload = null;
if (typeof raw === 'string') payload = tryJson(raw);
else if (raw && typeof raw === 'object') payload = raw;

let text = '';
let buttons = [];
if (payload && typeof payload === 'object') {
  text = typeof payload.text === 'string' ? payload.text : '';
  if (Array.isArray(payload.buttons)) buttons = payload.buttons;
}
if (!text && typeof raw === 'string') text = raw;
text = sanitize(String(text || ''));
if (!text) text = ' ';
if (text.length > 4096) text = text.slice(0, 4090) + '...';

let kb = [];
if (Array.isArray(buttons) && buttons.length) {
  const first = buttons[0];
  if (Array.isArray(first)) {
    kb = buttons.map(row => (row || []).filter(b => b && b.text).map(b => ({ text: String(b.text), callback_data: String(b.callback_data || b.text) })));
    kb = kb.filter(r => r.length);
  } else if (first && typeof first === 'object' && first.text) {
    kb = [(buttons || []).filter(b => b && b.text).map(b => ({ text: String(b.text), callback_data: String(b.callback_data || b.text) }))];
  }
}
const reply_markup = kb.length ? { inline_keyboard: kb } : null;
return [{ json: { agent_output_clean: text, reply_markup } }];

// Telegram consegna il vocale SENZA estensione (file_1468, application/octet-stream):
// Whisper deduce il formato dal nome file e lo rifiuta. Qui rinominiamo il binario col formato giusto.
const OK = ['flac','m4a','mp3','mp4','mpeg','mpga','oga','ogg','wav','webm'];
const MIME = { ogg:'audio/ogg', oga:'audio/ogg', mp3:'audio/mpeg', mpga:'audio/mpeg', mpeg:'audio/mpeg',
               m4a:'audio/m4a', mp4:'audio/mp4', wav:'audio/wav', webm:'audio/webm', flac:'audio/flac' };
const items = $input.all();
for (const item of items) {
  const bin = item.binary && item.binary.data;
  if (!bin) continue;
  const filePath = String(item.json?.result?.file_path || '');
  let ext = (filePath.split('.').pop() || '').toLowerCase();
  if (!OK.includes(ext)) {
    // fallback: mime del messaggio Telegram (audio/ogg per i vocali), altrimenti ogg
    const mime = String($('Normalizer (kind/text/file_id)').item.json.mime || '').toLowerCase();
    if (mime.includes('mpeg') || mime.includes('mp3')) ext = 'mp3';
    else if (mime.includes('mp4') || mime.includes('m4a')) ext = 'm4a';
    else if (mime.includes('wav')) ext = 'wav';
    else if (mime.includes('webm')) ext = 'webm';
    else ext = 'ogg';
  }
  bin.fileName = 'audio.' + ext;
  bin.fileExtension = ext;
  bin.mimeType = MIME[ext] || 'audio/ogg';
}
return items;

// Anti Doppio Tap 'Fine servizio' (22/07/2026)
// Il doppio tap sul bottone creava DUE righe recap identiche (race di 1s).
// Debounce 60s per chat via staticData: il secondo tap entro 60s viene ignorato.
const cb = $('Telegram Trigger1').first().json.callback_query || {};
const chatId = String((cb.message && cb.message.chat && cb.message.chat.id) || (cb.from && cb.from.id) || '');
const sd = $getWorkflowStaticData('global');
sd.fineTap = sd.fineTap || {};
const now = Date.now();
const last = Number(sd.fineTap[chatId] || 0);
if (chatId && (now - last) < 60000) {
  return [];
}
if (chatId) sd.fineTap[chatId] = now;
const unGiornoFa = now - 86400000;
for (const k of Object.keys(sd.fineTap)) {
  if (Number(sd.fineTap[k]) < unGiornoFa) delete sd.fineTap[k];
}
return items;

// Aggiunge la colonna Spese al riepilogo giornata (22/07/2026)
// Input: righe spese del foglio Recap (nodo Get Spese Oggi, filtrate per Autista, tutte le date).
// Tiene solo le spese con Data == Data del riepilogo e le compatta in una stringa.
const base = $('Code in JavaScript').first() ? $('Code in JavaScript').first().json : null;
if (!base || !base.IdChiusura) { return []; }
const s = v => String(v == null ? '' : v).trim();
const toN = v => { const n = Number(s(v).replace(',', '.').replace(/[^0-9.\-]/g, '')); return Number.isFinite(n) ? n : 0; };
const fmt = n => (Math.round(n * 100) / 100).toFixed(2).replace('.', ',');
let Spese = '';
try {
  const speseAll = $input.all().map(i => i.json).filter(r => r && (s(r.Tipologia) || s(r['€']) || s(r.Litri)));
  const speseGiorno = speseAll.filter(r => s(r.Data) === s(base.Data));
  if (speseGiorno.length) {
    const gruppi = {};
    let tot = 0, litri = 0;
    for (const r of speseGiorno) {
      const tip = s(r.Tipologia) || 'Altro';
      const imp = toN(r['€']);
      tot += imp;
      const l = toN(r.Litri);
      if (l) litri += l;
      let key;
      if (/rifornim|carburant|gasolio|cisterna/i.test(tip)) key = '⛽ Rifornimento';
      else if (/pasto/i.test(tip)) key = '🍽 Pasti';
      else if (/lavaggio/i.test(tip)) key = '🧼 Lavaggi';
      else key = '💶 ' + tip;
      gruppi[key] = (gruppi[key] || 0) + imp;
    }
    const parti = Object.entries(gruppi).map(function (kv) {
      const k = kv[0], v = kv[1];
      return (k.indexOf('⛽') === 0 && litri) ? (k + ' ' + fmt(litri) + ' L €' + fmt(v)) : (k + ' €' + fmt(v));
    });
    Spese = parti.join(' | ') + ' — Tot €' + fmt(tot);
  }
} catch (e) {
  Spese = '';
}
return [{ json: Object.assign({}, base, { Spese: Spese }) }];
